import type { ExamQuestion, ExamSection } from "./types";

type SourceQuestion = Omit<ExamQuestion, "number">;
type SourceQuiz = { quizId: number; label: string; questions: SourceQuestion[] };

// Licensed ElectricianTraining quiz imports generated from the site's mock_test_questions endpoint.

function numberQuestions(questions: SourceQuestion[]): ExamQuestion[] {
  return questions.map((question, index) => ({ number: index + 1, ...question }));
}

function cloneQuestion(question: ExamQuestion): ExamQuestion {
  return {
    ...question,
    options: { ...question.options },
    ...(question.imageUrls ? { imageUrls: [...question.imageUrls] } : {}),
    ...(question.optionImageUrls ? { optionImageUrls: { ...question.optionImageUrls } } : {})
  };
}

function cloneQuestions(questions: ExamQuestion[]): ExamQuestion[] {
  return questions.map(cloneQuestion);
}

function makeVariantSourceSection(id: string, title: string, quizzes: SourceQuiz[]): ExamSection {
  return {
    id,
    title,
    variants: quizzes.map((quiz) => ({
      id: "quiz-" + quiz.quizId,
      questions: cloneQuestions(numberQuestions(quiz.questions))
    }))
  };
}

